const raw =
  $json.website ||
  $json.Website ||
  $json['Website '] ||
  $json['Website Normalized'] ||
  $json.finalrequesturl ||
  $json.finalRequestUrl ||
  '';

if (!raw) {
  throw new Error('No website field found. Expected website, Website, Website , Website Normalized, finalrequesturl, or finalRequestUrl.');
}

let website = String(raw).trim();

if (!/^https?:\/\//i.test(website)) {
  website = `https://${website}`;
}

website = website.replace(/\s+/g, '');

const match = website.match(/^(https?:\/\/)([^\/?#]+)(\/[^?#]*)?/i);

if (!match) {
  throw new Error(`Could not parse website URL: ${website}`);
}

const protocol = match[1].toLowerCase();
const hostname = match[2].toLowerCase().replace(/^www\./, '');
const pathname = (match[3] || '').replace(/\/+$/, '');
const normalizedPath = pathname || '';
const normalizedWebsite = `${protocol}//${hostname}${normalizedPath}`;
const baseWebsite = `${protocol}//${hostname}`;
const normDomain = hostname;

const extractionPrompt = `You are extracting doctor-level dental providers from a dental practice page.

Return only real doctors who are presented by the practice as providers on the page.

Strict rules:
- Prefer names that appear in the page's doctor roster or "Meet Our Doctors" section.
- Ignore names that appear only inside reviews, testimonials, patient quotes, blog text, navigation, footer text, or marketing copy.
- Ignore names mentioned only in sentences like "I love Dr. X" or "Amazing experience with Dr. X" unless that same person also appears as a doctor heading/profile on the page.
- Do not invent or infer doctors from reviews.
- If a name appears as a heading with credentials like DDS, DMD, MSD, or MD in the doctor section, count it as a doctor.
- Return all real doctors in the doctor section, not just the first one.

Include:
- dentists
- orthodontists
- oral surgeons
- pediatric dentists
- endodontists
- periodontists
- prosthodontists
- practicing owners

Exclude:
- hygienists
- assistants
- office managers
- front desk staff
- coordinators
- names that appear only in testimonials or reviews

Return a JSON array called "doctors".

For each doctor include:
full_name
first_name
last_name
role_title
specialty
bio_page_url
source_page_url
confidence`;

const extractionSchema = {
  type: 'object',
  properties: {
    practice_name: { type: ['string', 'null'] },
    doctors: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          full_name: { type: ['string', 'null'] },
          first_name: { type: ['string', 'null'] },
          last_name: { type: ['string', 'null'] },
          role_title: { type: ['string', 'null'] },
          specialty: { type: ['string', 'null'] },
          bio_page_url: { type: ['string', 'null'] },
          source_page_url: { type: ['string', 'null'] },
          confidence: { type: ['number', 'null'] }
        },
        required: [
          'full_name',
          'first_name',
          'last_name',
          'role_title',
          'specialty',
          'bio_page_url',
          'source_page_url',
          'confidence'
        ]
      }
    }
  },
  required: ['practice_name', 'doctors']
};

return {
  json: {
    ...$json,
    website: normalizedWebsite,
    base_website: baseWebsite,
    norm_domain: normDomain,
    extraction_prompt: extractionPrompt,
    extraction_schema: extractionSchema,
    lane_used: null,
    extraction_status: 'started'
  }
};

