const laneInfo = $json;
const pages = Array.isArray($json.data) ? $json.data : [];

const providerMap = new Map();

const banWords = [
  "hygienist",
  "assistant",
  "front desk",
  "coordinator",
  "office manager",
  "treatment coordinator",
  "insurance coordinator",
  "business assistant"
];

function normalizeName(name = "") {
  return String(name)
    .replace(/\bdr\.?\s*/ig, "")
    .replace(/,\s*(dds|dmd|msd|md)/ig, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function stripCredentials(name = "") {
  return String(name)
    .replace(/,\s*(dds|dmd|msd|md)/ig, "")
    .trim();
}

function parseNameParts(fullName = "") {
  const cleaned = stripCredentials(
    String(fullName).replace(/\bdr\.?\s*/ig, "").trim()
  );

  const parts = cleaned.split(/\s+/).filter(Boolean);

  return {
    first_name: parts[0] || null,
    last_name: parts.length > 1 ? parts.slice(1).join(" ") : null
  };
}

function scoreCandidate(candidate) {
  let score = 0;

  const fullName = String(candidate?.full_name || "").trim();
  const firstName = String(candidate?.first_name || "").trim();
  const lastName = String(candidate?.last_name || "").trim();
  const roleTitle = String(candidate?.role_title || "").toLowerCase();
  const specialty = String(candidate?.specialty || "").trim();
  const bioPageUrl = String(candidate?.bio_page_url || "").trim();
  const sourcePageUrl = String(candidate?.source_page_url || "").trim();
  const confidence = typeof candidate?.confidence === "number" ? candidate.confidence : 0;

  const hasCredentials = /\b(DDS|DMD|MSD|MD)\b/i.test(fullName);
  const isGenericDrLast = /^Dr\.?\s+[A-Z][a-z'.-]+$/i.test(fullName);
  const hasFullFirstLast = !!(firstName && lastName);

  if (hasCredentials) score += 5;
  if (hasFullFirstLast) score += 4;
  if (bioPageUrl) score += 3;
  if (sourcePageUrl) score += 2;
  if (specialty) score += 1;
  if (roleTitle.includes("dentist")) score += 1;

  score += confidence;

  if (isGenericDrLast) score -= 4;

  return score;
}

function upsertDoctor(candidate) {
  const name = String(candidate?.full_name || "").trim();
  if (!name) return;

  const role = String(candidate?.role_title || "").toLowerCase();
  if (banWords.some(w => role.includes(w))) return;

  const key = normalizeName(name);
  if (!key) return;

  const existing = providerMap.get(key);

  if (!existing) {
    providerMap.set(key, candidate);
    return;
  }

  if (scoreCandidate(candidate) > scoreCandidate(existing)) {
    providerMap.set(key, { ...existing, ...candidate });
  }
}

for (const page of pages) {

  const extracted =
    page?.json ||
    page?.data?.json ||
    page?.metadata?.json ||
    {};

  const practiceName = extracted.practice_name || null;

  const extractedDoctors = Array.isArray(extracted.doctors)
    ? extracted.doctors
    : [];

  for (const d of extractedDoctors) {

    const name = String(d?.full_name || "").trim();
    if (!name) continue;

    upsertDoctor({
      full_name: d.full_name || null,
      first_name: d.first_name || null,
      last_name: d.last_name || null,
      role_title: d.role_title || "Dentist",
      specialty: d.specialty || null,
      bio_page_url: d.bio_page_url || null,
      source_page_url:
        d.source_page_url ||
        page?.metadata?.url ||
        null,
      confidence: typeof d.confidence === "number" ? d.confidence : 0.9,
      source_lane: laneInfo.lane_label,
      practice_name_extracted: practiceName
    });
  }

  const markdown =
    page?.markdown ||
    page?.data?.markdown ||
    page?.content?.markdown ||
    "";

  if (!markdown) continue;

  const text = String(markdown);

  const credentialMatches = [
    ...text.matchAll(/\b([A-Z][A-Za-z.'-]+\s+[A-Z][A-Za-z.'-]+,\s*(DDS|DMD|MD))\b/gm),
    ...text.matchAll(/\b(Dr\.?\s+[A-Z][A-Za-z.'-]+\s+[A-Z][A-Za-z.'-]+,\s*(DDS|DMD|MD))\b/gm)
  ];

  for (const match of credentialMatches) {

    const fullName = String(match[1] || "").trim();
    if (!fullName) continue;

    const parts = parseNameParts(fullName);

    upsertDoctor({
      full_name: fullName,
      first_name: parts.first_name,
      last_name: parts.last_name,
      role_title: "Dentist",
      specialty: null,
      bio_page_url: page?.metadata?.url || null,
      source_page_url: page?.metadata?.url || null,
      confidence: 0.92,
      source_lane: laneInfo.lane_label,
      practice_name_extracted: practiceName
    });

  }

  const genericMatches = [
    ...text.matchAll(/\b(Dr\.?\s+[A-Z][a-z]+)\b/gm)
  ];

  for (const match of genericMatches) {

    const fullName = String(match[1] || "").trim();
    if (!fullName) continue;

    const parts = parseNameParts(fullName);

    upsertDoctor({
      full_name: fullName,
      first_name: parts.first_name,
      last_name: parts.last_name,
      role_title: "Dentist",
      specialty: null,
      bio_page_url: page?.metadata?.url || null,
      source_page_url: page?.metadata?.url || null,
      confidence: 0.5,
      source_lane: laneInfo.lane_label,
      practice_name_extracted: practiceName
    });

  }
}

const rawDoctors = [...providerMap.values()];

for (const d of rawDoctors) {

  const genericMatch = String(d.full_name || "").match(/^Dr\.?\s+([A-Z][a-z]+)$/i);
  if (!genericMatch) continue;

  const genericLast = genericMatch[1].toLowerCase();

  const fuller = rawDoctors.find(x => {

    const full = String(x.full_name || "");
    const hasCreds = /\b(DDS|DMD|MD)\b/i.test(full);
    const last = String(x.last_name || "").toLowerCase();

    return hasCreds && last === genericLast;

  });

  if (fuller) {

    d.full_name = fuller.full_name;
    d.first_name = fuller.first_name;
    d.last_name = fuller.last_name;
    d.bio_page_url = fuller.bio_page_url || d.bio_page_url;
    d.source_page_url = fuller.source_page_url || d.source_page_url;
    d.confidence = Math.max(d.confidence || 0, fuller.confidence || 0);

  }
}

const bestByNormalized = new Map();

for (const d of rawDoctors) {

  const key = normalizeName(d.full_name || "");
  if (!key) continue;

  const existing = bestByNormalized.get(key);

  if (!existing || scoreCandidate(d) > scoreCandidate(existing)) {
    bestByNormalized.set(key, d);
  }

}

const byLastName = new Map();

for (const d of bestByNormalized.values()) {

  const last = String(d.last_name || "").toLowerCase();
  const bucket = last || normalizeName(d.full_name);

  if (!byLastName.has(bucket)) byLastName.set(bucket, []);
  byLastName.get(bucket).push(d);

}

const finalDoctors = [];

for (const candidates of byLastName.values()) {

  candidates.sort((a, b) => scoreCandidate(b) - scoreCandidate(a));
  finalDoctors.push(candidates[0]);

}

finalDoctors.sort((a, b) => scoreCandidate(b) - scoreCandidate(a));

return {
  json: {
    ...laneInfo,
    lane_used: laneInfo.lane_label,
    extraction_status: finalDoctors.length ? "success" : "fallback_required",
    doctor_count: finalDoctors.length,
    doctors: finalDoctors
  }
};

const base = $json.base_website;
const candidates = [
  `${base}/team`,
  `${base}/our-team`,
  `${base}/meet-the-team`,
  `${base}/meet-our-team`,
  `${base}/doctors`,
  `${base}/our-doctors`,
  `${base}/meet-the-doctors`,
  `${base}/providers`,
  `${base}/our-providers`,
  `${base}/staff`,
  `${base}/about`,
  `${base}/about-us`
];
const unique = [...new Set(candidates.map(x => x.replace(/([^:]\/)\/+/, '$1')))];
return {
  json: {
    ...$json,
    candidate_urls_lane2: unique,
    lane_label: 'lane_2_targeted_urls'
  }
};

