      confidence: typeof d.confidence === 'number' ? d.confidence : null,
      source_lane: laneInfo.lane_label,
      practice_name_extracted: practiceName
    };
    if (!current || (candidate.confidence ?? 0) > (current.confidence ?? 0)) {
      providerMap.set(key, candidate);
    }
  }
}

const doctors = [...providerMap.values()];
return {
  json: {
    ...laneInfo,
    lane_used: laneInfo.lane_label,
    extraction_status: doctors.length ? 'success' : 'fallback_required',
    doctor_count: doctors.length,
    doctors
  }
};

const upstream = $json;
const links = Array.isArray($json.links) ? $json.links : [];

function scoreUrl(u = '') {
  const x = String(u).toLowerCase();
  let s = 0;

  if (x.includes('team')) s += 5;
  if (x.includes('doctor')) s += 5;
  if (x.includes('dentist')) s += 5;
  if (x.includes('provider')) s += 4;
  if (x.includes('meet')) s += 3;
  if (x.includes('about')) s += 2;
  if (x.includes('staff')) s += 2;
  if (x.includes('orthodont')) s += 4;
  if (x.includes('oral-surgeon') || x.includes('oral_surgeon')) s += 4;
  if (x.includes('pediatric')) s += 4;
  if (x.includes('endodont')) s += 4;
  if (x.includes('periodont')) s += 4;
  if (x.includes('prosthodont')) s += 4;

  if (x.includes('blog')) s -= 6;
  if (x.includes('privacy')) s -= 10;
  if (x.includes('career')) s -= 7;
  if (x.includes('forms')) s -= 6;
  if (x.includes('financing')) s -= 4;
  if (x.includes('insurance')) s -= 3;

  return s;
}

const filtered = links
  .map(l => typeof l === 'string' ? { url: l } : l)
  .filter(l => l && l.url)
  .map(l => ({ ...l, score: scoreUrl(l.url) }))
  .filter(l => l.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 8)
  .map(l => l.url);

return {
  json: {
    ...upstream,
    candidate_urls_lane3: filtered,
    lane_label: 'lane_3_map_rescue'
  }
};

