const laneInfo = $json;
const pages = Array.isArray($json.data) ? $json.data : [];
const providerMap = new Map();
const banWords = ['hygienist','assistant','front desk','office manager','treatment coordinator','patient coordinator','insurance coordinator','business assistant'];

for (const page of pages) {
  const extracted = page?.json || page?.data?.json || page?.metadata?.json || {};
  const practiceName = extracted.practice_name || null;
  const doctors = Array.isArray(extracted.doctors) ? extracted.doctors : [];
  for (const d of doctors) {
    const name = (d?.full_name || '').trim();
    if (!name) continue;
    const role = String(d?.role_title || '').toLowerCase();
    if (banWords.some(w => role.includes(w))) continue;
    const key = name.toLowerCase();
    const current = providerMap.get(key);
    const candidate = {
      full_name: d.full_name || null,
      first_name: d.first_name || null,
      last_name: d.last_name || null,
      role_title: d.role_title || null,
      specialty: d.specialty || null,
      bio_page_url: d.bio_page_url || null,
      source_page_url: d.source_page_url || page?.metadata?.url || page?.metadata?.sourceURL || null,
      confidence: typeof d.confidence === 'number' ? d.confidence : null,
      source_lane: laneInfo.lane_label,
      practice_name_extracted: practiceName
    };
    if (!current || (candidate.confidence ?? 0) > (current.confidence ?? 0)) {
      providerMap.set(key, candidate);
    }
  }
}

const doctors = [...providerMap.values()];
return {
  json: {
    ...laneInfo,
    lane_used: laneInfo.lane_label,
    extraction_status: doctors.length ? 'success' : 'manual_review_required',
    doctor_count: doctors.length,
    doctors,
    fail_reason: doctors.length ? null : 'no_providers_found_after_all_lanes'
  }
};

function pickTopDoctors(doctors) {
  const arr = Array.isArray(doctors) ? doctors.slice() : [];

  arr.sort((a, b) => {
    const ac = typeof a?.confidence === 'number' ? a.confidence : -1;
    const bc = typeof b?.confidence === 'number' ? b.confidence : -1;
    return bc - ac;
  });

  return arr.slice(0, 3);
}

return $input.all().map(item => {
  const j = item.json;

  const doctors = Array.isArray(j.doctors) ? j.doctors : [];
  const topDoctors = pickTopDoctors(doctors);

  const normDomain = j.norm_domain || null;
  const website = j.website || null;
  const baseWebsite = j.base_website || null;
  const practiceNameInput = j.practice_name || j["Practice Name"] || j.practice_name_input || null;

  const practiceNameExtracted =
    topDoctors.find(d => d?.practice_name_extracted)?.practice_name_extracted ||
    j.practice_name_extracted ||
    null;

  const failReason = j.fail_reason || null;
  const extractionStatus = j.extraction_status || null;
  const laneUsed = j.lane_used || null;

  const isBadDomain =
    String(failReason || '').toLowerCase().includes('bad_domain') ||
    String(failReason || '').toLowerCase().includes('bad domain') ||
    String(extractionStatus || '').toLowerCase() === 'bad_domain';

  const existingOwnerName = j["Owner Name"] || j.owner_name || null;

  const ownerName = existingOwnerName
    ? existingOwnerName
    : (isBadDomain && normDomain ? `BAD DOMAIN: ${normDomain}` : null);

  const row = {
    practice_unique_key: j.practice_unique_key || j["Practice Unique Key"] || normDomain || website || null,
    NormDomain: normDomain,
    Website: website,
    "Base Website": baseWebsite,
    "Practice Name Input": practiceNameInput,
    "Practice Name Extracted": practiceNameExtracted,
    Phone: j.phone || j.Phone || null,
    Address: j.address || j.Address || null,
    "Owner Name": ownerName,
    "Providers Count": Number(j.doctor_count || doctors.length || 0),
    "Extraction Status": extractionStatus,
    "Lane Used": laneUsed,
    "Fail Reason": failReason
  };

  for (let i = 0; i < 3; i++) {
    const d = topDoctors[i] || {};
    const n = i + 1;

    row[`Doctor ${n} Full Name`] = d.full_name || null;
    row[`Doctor ${n} First Name`] = d.first_name || null;
    row[`Doctor ${n} Last Name`] = d.last_name || null;
    row[`Doctor ${n} Role Title`] = d.role_title || null;
    row[`Doctor ${n} Specialty`] = d.specialty || null;
    row[`Doctor ${n} Bio Page URL`] = d.bio_page_url || null;
    row[`Doctor ${n} Source Page URL`] = d.source_page_url || null;
    row[`Doctor ${n} Confidence`] = d.confidence ?? null;
  }

  return { json: row };
});

const base = $json.base_website || $json.website || '';

if (!base || !/^https?:\/\//i.test(String(base))) {
  return {
    json: {
      ...$json,
      lane1_candidate_urls: [],
      lane1_candidate_url_objects: [],
      fail_reason: 'invalid_or_missing_base_website'
    }
  };
}

const cleanBase = String(base).replace(/\/+$/, '');

const patterns = [
  ['/meet-the-dentist', 100],
  ['/meet-the-dentists', 99],
  ['/dentists', 98],
  ['/dentist', 96],
  ['/our-doctors', 95],
  ['/doctors', 94],
  ['/doctor', 92],
  ['/providers', 90],
  ['/our-providers', 88],
  ['/our-team', 86],
  ['/team', 84],
  ['/staff', 70],
  ['/about', 55],
  ['/about-us', 54]
];

const candidates = patterns.map(([path, score]) => ({
  url: `${cleanBase}${path}`,
  score,
  source: 'pattern'
}));

return {
  json: {
    ...$json,
    lane1_candidate_url_objects: candidates,
    lane1_candidate_urls: candidates.map(x => x.url)
  }
};

const candidates = Array.isArray($json.lane1_candidate_url_objects)
  ? $json.lane1_candidate_url_objects
  : [];

const top = candidates
  .sort((a, b) => b.score - a.score)
  .slice(0, 3); // Adjust to 2–3 depending on Firecrawl credit usage

return {
  json: {
    ...$json,
    lane1_candidate_url_objects: top,
    lane1_candidate_urls: top.map(x => x.url)
  }
};
